WITH valid_stores AS (SELECT * FROM stores WHERE city IN ('London', 'Chiang Mai') AND (store_name LIKE 'S%' OR region IS NULL)), summary AS (SELECT CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END opened_cohort, COUNT(sqft) sqft_count, SORT_ARRAY(COLLECT_SET(city)) city_list FROM valid_stores GROUP BY CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT opened_cohort, city_list FROM summary;
